$VRT_LABOS_JSON = <<<'JSON'
{"lv10":{"experience":["1️⃣ CALORIMÈTRE — MESURE DE C : verse 200g d'eau à 20°C dans un calorimètre. Chauffe un bloc de métal à 100°C, plonge-le dans l'eau. Mesure la température finale T_éq. Applique : m_métal×c_métal×(100-T_éq) = m_eau×4180×(T_éq-20). Déduis c_métal.","2️⃣ CHANGEMENT D'ÉTAT — PALIER : mets des glaçons dans un bécher. Chauffe à puissance constante. Relève T toutes les minutes. Trace la courbe. Observe : pendant la fonte (0°C), T ne change pas malgré le chauffage → énergie absorbée = chaleur latente L.","3️⃣ MÉLANGE D'EAU : mesure 100g d'eau chaude (T₁=80°C) dans un bécher, 100g d'eau froide (T₂=20°C) dans un autre. Mélange. Mesure T_eq. Compare avec la prévision : T_eq = (T₁+T₂)/2 = 50°C. Pourquoi l'écart ?","4️⃣ SERINGUE ET GAZ (loi de Boyle) : bouche une seringue avec le doigt (V constant). Essaie de comprimer. Ressens la pression augmenter. Avec une seringue + manomètre : comprime le volume de moitié → la pression double.","5️⃣ DILATATION THERMIQUE : chauffe un ballon en caoutchouc partiellement gonflé. Observe : il gonfle davantage (gaz se dilate). Refroidis : il se dégonfle. La pression à volume constant augmente avec T.","6️⃣ ISOLATION THERMIQUE : mets de l'eau chaude (60°C) dans deux récipients : l'un bien isolé (coton, polystyrène), l'autre nu. Mesure la température toutes les 5 minutes pendant 30 min. Compare les courbes de refroidissement.","7️⃣ COMBUSTION ET CALORIMÉTRIE : brûle une noix ou un morceau de biscuit sous un bécher d'eau. Mesure ΔT de l'eau. Calcule Q = m×4180×ΔT. Estime l'énergie (kJ/g) contenue dans l'aliment."],"quiz":[{"q":"On chauffe 1kg d'eau (c=4180) de 20°C à 70°C :","opts":["4 180 J","41 800 J","209 000 J","418 000 J"],"ans":2,"exp":"Q = 1×4180×50 = 209 000 J."},{"q":"27°C en Kelvin :","opts":["27 K","127 K","300 K","327 K"],"ans":2,"exp":"T(K) = T(°C) + 273 = 300 K."},{"q":"La chaleur latente correspond à :","opts":["L'énergie pour chauffer","L'énergie pour changer d'état à T constante","La capacité thermique","La conduction"],"ans":1,"exp":"Chaleur latente = énergie de changement d'état sans variation de température (fusion, vaporisation)."},{"q":"Gaz à 200kPa et 400K, chauffé à 800K (V=cste). Nouvelle pression :","opts":["100 kPa","200 kPa","400 kPa","800 kPa"],"ans":2,"exp":"Gay-Lussac : P/T = cste → P₂ = 200×800/400 = 400 kPa."},{"q":"L'eau a une capacité thermique plus élevée que le fer. Donc :","opts":["L'eau chauffe plus vite","L'eau nécessite plus d'énergie pour la même ΔT","L'eau conduit mieux","L'eau bout plus vite"],"ans":1,"exp":"c_eau=4180 >> c_fer=450 → l'eau stocke beaucoup d'énergie (régulateur thermique : océans, radiateurs)."}]},"lv11":{"experience":["1️⃣ RÉACTION Zn/CuSO₄ : plonge une lame de zinc dans une solution bleue de sulfate de cuivre (CuSO₄). Observe sur 5 minutes : dépôt rougeâtre sur la lame (cuivre métallique) et décoloration progressive de la solution.","2️⃣ RÉACTION Cu/ZnSO₄ : plonge une lame de cuivre dans une solution de sulfate de zinc (ZnSO₄). Observe : aucune réaction. Conclusion : Zn est meilleur réducteur que Cu. Ordre de réactivité.","3️⃣ CONSTRUCTION DE LA PILE Zn/Cu : prépare 2 béchers (ZnSO₄ + lame Zn ; CuSO₄ + lame Cu). Relie par un pont salin (papier filtre trempé dans KNO₃). Branche un voltmètre : lis ≈ 1,1 V.","4️⃣ COMBUSTION DU MAGNÉSIUM : brûle un ruban de Mg dans l'air avec une pince. Observe : flamme blanche éblouissante (NE PAS REGARDER DIRECTEMENT). Résidu blanc = MgO. Équation : 2Mg + O₂ → 2MgO.","5️⃣ ÉQUILIBRAGE D'ÉQUATION (procédure) : pour C₃H₈ + O₂ → CO₂ + H₂O, compte les atomes avant et après. Ajoute des coefficients pour égaliser : C₃H₈ + 5O₂ → 3CO₂ + 4H₂O. Vérifie chaque élément.","6️⃣ CORROSION DU FER : observe des clous dans 3 tubes (eau + air, eau seule, air sec). Après 1 semaine : rouille dans le tube avec eau + air uniquement. Rôle de l'eau ET de l'oxygène confirmé.","7️⃣ ÉLECTROLYSE DÉMONSTRATION : place deux électrodes en carbone dans de l'eau salée. Branche une pile 9V. Observe : bulles aux deux électrodes (H₂ à la cathode, O₂ à l'anode). L'eau se décompose !"],"quiz":[{"q":"Zn + Cu²⁺ → Zn²⁺ + Cu. Quel élément est oxydé ?","opts":["Cu²⁺","Cu","Zn²⁺","Zn"],"ans":3,"exp":"Zn perd 2 électrons (0→+2) = oxydé (OIL). Cu²⁺ gagne 2e⁻ (+2→0) = réduit (RIG)."},{"q":"N.o. de l'oxygène dans H₂O :","opts":["+2","+1","-1","-2"],"ans":3,"exp":"O très électronégatif → n.o. = -2 dans la plupart des composés."},{"q":"Dans une pile, l'oxydation a lieu :","opts":["À la cathode","Au pont salin","À l'anode","Dans les deux"],"ans":2,"exp":"ANODE = Oxydation (A-O). Cathode = Réduction (C-R)."},{"q":"Combustion complète de CH₄ donne :","opts":["CO + H₂O","CO₂ + H₂","CO₂ + H₂O","CH₃OH + O"],"ans":2,"exp":"CH₄ + 2O₂ → CO₂ + 2H₂O. Complète = CO₂. Incomplète = CO (toxique)."},{"q":"La galvanisation protège le fer en le couvrant de :","opts":["Chrome","Cuivre","Zinc","Étain"],"ans":2,"exp":"Zinc plus réducteur que fer → se sacrifie en premier (protection cathodique)."}]},"lv14":{"experience":["1️⃣ Mendel : VV (violette) × vv (blanche) → F1 : 100% Vv (violettes). V dominant.","2️⃣ Tableau de Punnett Vv×Vv : VV + 2Vv + vv = 3 violettes : 1 blanche (ratio 3:1).","3️⃣ Dihybridisme AABB × aabb → F1 : AaBb. F1×F1 → F2 : 9 A_B_ : 3 A_bb : 3 aaB_ : 1 aabb.","4️⃣ Groupes sanguins : père IAi (A) × mère IBi (B) → IAIB (AB), IAi (A), IBi (B), ii (O). 4 groupes possibles !","5️⃣ Daltonisme (lié X) : mère XᴰX (porteuse) × père XᴰY → 50% fils daltoniens.","6️⃣ Drépanocytose : HbA/HbS × HbA/HbS → 25% risque enfant malade (HbS/HbS).","7️⃣ Arbre généalogique : détermine le mode de transmission d'une maladie (dominant/récessif/lié X)."],"quiz":[{"q":"Croisement Vv × Vv (V dominant). Ratio phénotypique F2 :","opts":["1:1:1:1","1:2:1","3:1","1:1"],"ans":2,"exp":"Vv×Vv → 1VV + 2Vv + 1vv = 3 phénotype V_ (violette) : 1 vv (blanche)."},{"q":"Le phénotype est :","opts":["Le matériel génétique","L'ensemble des allèles","Le caractère observable","La séquence ADN complète"],"ans":2,"exp":"Phénotype = caractère observable (couleur yeux, taille, groupe sanguin). Génotype = constitution allélique."},{"q":"IA et IB pour les groupes sanguins ABO sont :","opts":["IA dominant sur IB","IB dominant sur IA","Codominants","Les deux récessifs"],"ans":2,"exp":"IA et IB codominants → individu IAIB exprime les DEUX antigènes → groupe AB."},{"q":"Le daltonisme (lié à X) touche surtout :","opts":["Les filles","Les garçons","Les deux sexes","Uniquement les homozygotes"],"ans":1,"exp":"Garçons XY : un seul allèle X → si défectueux, maladie exprimée. Filles XX : peuvent être porteuses."},{"q":"Croisement AA × aa. F1 est :","opts":["AA","aa","100% Aa","1/2 AA + 1/2 aa"],"ans":2,"exp":"1ère loi (uniformité) : P1 AA × P2 aa → F1 : 100% Aa."}]},"lv16":{"experience":["1️⃣ TRACER LA COURBE : prends f(x)=x² sur [-3;3]. Construis le tableau de valeurs (x=-3,-2,-1,0,1,2,3 → f=9,4,1,0,1,4,9). Place les points sur papier millimétré. Trace la parabole en reliant les points.","2️⃣ PENTE D'UNE TANGENTE : sur ta courbe de x², dessine la tangente au point x=1. Mesure sa pente (montée/base). Compare avec la valeur de f'(1)=2×1=2. Est-ce cohérent ?","3️⃣ TABLEAU DE VARIATIONS : f(x)=x²-4x+3 → f'(x)=2x-4. Résous f'(x)=0 → x=2. Signe de f' : négatif sur ]-∞,2[, positif sur ]2,+∞[. Complète le tableau (flèche ↘ puis ↗).","4️⃣ EXTREMUM LOCAL : d'après ton tableau, f est décroissante avant x=2 et croissante après → x=2 est un MINIMUM. Calcule f(2)=4-8+3=-1. C'est la valeur minimale de f.","5️⃣ APPLICATION AU PROBLÈME CONCRET : un agriculteur veut clôturer un jardin rectangulaire de périmètre 40m. Surface S = x×(20-x). Dérive et trouve le max de S → x=10m (carré de 10×10).","6️⃣ CALCUL DE DÉRIVÉES (exercice guidé) : dérive les fonctions suivantes en utilisant les formules : f(x)=3x⁴ → f'=? ; g(x)=5x²+2x → g'=? ; h(x)=√x → h'=? Vérifie tes réponses.","7️⃣ INTÉGRALE (Tle) — AIRE SOUS LA COURBE : sur le graphe de f(x)=x entre 0 et 4, l'aire est un triangle de base 4 et hauteur 4. Aire = ½×4×4=8. Vérifie : ∫₀⁴ x dx = [x²/2]₀⁴ = 8 ✓"],"quiz":[{"q":"Dérivée de f(x)=5x³ :","opts":["5x²","15x²","x³","15x³"],"ans":1,"exp":"(5x³)'=5×3x²=15x²."},{"q":"Si f'(x)>0 sur un intervalle, f est :","opts":["Décroissante","Constante","Croissante","Convexe"],"ans":2,"exp":"f'(x)>0 ↔ pente positive ↔ f croissante."},{"q":"Dérivée de ln(x) :","opts":["x","1/x","ln(x)/x","eˣ"],"ans":1,"exp":"(ln x)'=1/x pour x>0."},{"q":"f(x)=x²-4x+3. f'(x)=0 en x=?","opts":["1","2","3","-2"],"ans":1,"exp":"f'(x)=2x-4=0 → x=2. Minimum (f''=2>0)."},{"q":"∫₀² x dx = ?","opts":["2","4","1","0"],"ans":0,"exp":"[x²/2]₀²=4/2-0=2."},{"q":"Dérivée de eˣ :","opts":["xeˣ⁻¹","eˣ","xeˣ","1/eˣ"],"ans":1,"exp":"(eˣ)'=eˣ. La fonction exponentielle est sa propre dérivée."}]},"lv18":{"experience":["1️⃣ Trace les grandes routes maritimes : Canal Suez, Canal Panama, détroit Malacca, Cap Bonne Espérance.","2️⃣ FMN Apple : conçu Californie → assemblé Chine → vendu mondialement. Fragmentation chaîne de valeur.","3️⃣ IDH Cameroun 2023 ≈ 0,576 (moyen). Comparer : Norvège (0,97), Niger (0,40).","4️⃣ Migrations camerounaises : diaspora en France, USA, UK. Transferts de fonds ≈ 300M$/an.","5️⃣ Villes mondiales (global cities) : New York, Londres, Tokyo, Shanghai. Critères : CBD, bourse, FMN, hub aérien.","6️⃣ Mondialisation culturelle : 'McDonaldisation' vs résistances locales. Francophonie comme levier.","7️⃣ Débat : mondialisation = opportunité ou menace pour le Cameroun ? Argumentez avec des données."],"quiz":[{"q":"La mondialisation désigne :","opts":["La standardisation de la cuisine","La mise en relation croissante des économies mondiales","La création de l'Union Africaine","La colonisation du Sud"],"ans":1,"exp":"Mondialisation = intégration des marchés, capitaux, personnes et informations à l'échelle mondiale."},{"q":"Les BRICS regroupent :","opts":["USA,UK,Inde,Chine,Suisse","Brésil,Russie,Inde,Chine,Afrique du Sud","Bangladesh,Rwanda,Inde,Corée,Suède","Belgique,Russie,Iran,Cameroun,Sénégal"],"ans":1,"exp":"BRICS = puissances émergentes contestant la domination de la triade USA-Europe-Japon."},{"q":"L'IDH mesure :","opts":["Uniquement le PIB","La richesse des FMN","Le développement humain (revenus+santé+éducation)","La superficie"],"ans":2,"exp":"IDH (ONU) : combine espérance de vie, niveau d'éducation et revenu/habitant. Entre 0 et 1."},{"q":"Le port de Douala est important car :","opts":["1er port d'Afrique","Hub pour pays enclavés d'Afrique centrale","Exporte uniquement du pétrole","Appartient à une FMN américaine"],"ans":1,"exp":"Douala = hub logistique pour Cameroun, Tchad, RCA — pays sans accès à la mer."},{"q":"Une firme multinationale (FMN) :","opts":["Emploie > 1000 personnes","Produit et vend dans plusieurs pays","Appartient à l'État","Exporte uniquement"],"ans":1,"exp":"FMN = entreprise avec filiales de production/commercialisation dans plusieurs pays (Total, Samsung, Dangote)."}]},"lv30":{"experience":["1️⃣ COMPOSITION U-235 : Z=92 protons, A=235 → N=143 neutrons. Symbole : ^235_92 U. Très instable, fissile.","2️⃣ DÉSINTÉGRATION α : ^238_92 U → ^234_90 Th + ^4_2 He. Vérifier : Z: 92=90+2 ✓ ; A: 238=234+4 ✓.","3️⃣ DÉSINTÉGRATION β⁻ : ^14_6 C → ^14_7 N + e⁻. Un neutron du C devient proton (Z↑1). Datation au C-14 utilise cette propriété (T=5730 ans).","4️⃣ DEMI-VIE : iode-131 (T=8 jours). Après 24 jours = 3 demi-vies. Fraction restante = (1/2)³ = 1/8 = 12,5%. Si N₀=400 atomes → 50 restants.","5️⃣ DATATION C-14 : un fossile contient 25% du C-14 normal. 25% = (1/2)² → 2 demi-vies = 2×5730 = 11 460 ans.","6️⃣ FISSION U-235 : neutron + ^235_92 U → ^141_56 Ba + ^92_36 Kr + 3 neutrons + 200 MeV. Les 3 neutrons fissent d'autres U-235 → réaction en chaîne (bombe A) ou contrôlée (centrale).","7️⃣ FUSION DANS LE SOLEIL : 4 ^1_1 H → ^4_2 He + 2 positrons + 2 neutrinos + énergie. Température requise : 15 millions K (cœur Soleil). Sur Terre : ITER tente la reproduction."],"quiz":[{"q":"L'uranium-235 contient combien de neutrons ?","opts":["92","143","235","327"],"ans":1,"exp":"^235_92 U : A=235, Z=92 protons. N=A-Z=235-92=143 neutrons."},{"q":"Désintégration α : Z et A changent comment ?","opts":["Z↑2, A=cst","Z=cst, A↓4","Z↓2, A↓4","Z↓1, A=cst"],"ans":2,"exp":"α = ^4_2 He éjecté. Le noyau perd 2 protons (Z↓2) et 2 neutrons (A↓4)."},{"q":"Iode-131 (T=8j). Après 32 jours, fraction restante :","opts":["1/4","1/8","1/16","1/32"],"ans":2,"exp":"32j = 4 demi-vies. Fraction = (1/2)⁴ = 1/16."},{"q":"Centrale nucléaire utilise quel phénomène ?","opts":["Fusion","Fission","Combustion","Désintégration alpha"],"ans":1,"exp":"Centrale = fission de U-235 ou Pu-239 contrôlée. Fusion = pas encore maîtrisée pour énergie."},{"q":"Énergie du Soleil provient de :","opts":["Combustion","Fusion H→He","Fission","Géothermie"],"ans":1,"exp":"Au cœur du Soleil (15 millions K), 4 H → 1 He + énergie via fusion. Perte de masse convertie en E selon E=mc²."},{"q":"Un échantillon : 25% C-14 restant. Âge ?","opts":["5730 ans","11 460 ans","17 190 ans","Indéterminable"],"ans":1,"exp":"25% = (1/2)² → 2 demi-vies × 5730 = 11 460 ans."}]},"lv33":{"experience":["1️⃣ ALGO TRI BULLES (Python-like) :\n  for i de 0 à n-1:\n    for j de 0 à n-i-1:\n      si t[j] > t[j+1]:\n        échanger(t[j], t[j+1])\nDessine les étapes sur [5,3,8,1].","2️⃣ ÉTAPES SUR [5,3,8,1] :\nPassage 1: [3,5,8,1] → [3,5,8,1] → [3,5,1,8]\nPassage 2: [3,5,1,8] → [3,1,5,8] → fini\nPassage 3: [1,3,5,8] → trié !","3️⃣ COMPTER LES COMPARAISONS : pour n=4, max = 4×3 = 12 comparaisons. Pour n=10 = 90. Pour n=1000 = 1 million. Quadratique.","4️⃣ TRI PAR SÉLECTION : trouver le min, le mettre en 1er. Recommencer avec [1:]. Aussi O(n²) mais moins d'échanges.","5️⃣ RECHERCHE DICHOTOMIQUE (tableau trié) : couper en 2 à chaque étape. n=1 000 000 → 20 comparaisons (log₂ 10⁶). C'est pourquoi le tri préalable est utile.","6️⃣ QUICKSORT — PIVOT : choisir t[0]=5 dans [5,3,8,1,4]. Partition : <5 → [3,1,4], =5 → [5], >5 → [8]. Récursion sur chaque partie.","7️⃣ COMPARER PERFORMANCES : n=10⁶ éléments. Tri bulles : 10¹² ops (~17 min). Quicksort : 2×10⁷ ops (~20 ms). Différence x50 000 !"],"quiz":[{"q":"Complexité du tri à bulles pire cas :","opts":["O(n)","O(n²)","O(n log n)","O(1)"],"ans":1,"exp":"Tri à bulles : 2 boucles imbriquées → O(n²). Pour n=1000, ~10⁶ opérations."},{"q":"Algorithme le plus rapide pour grands n :","opts":["Tri à bulles O(n²)","Tri par sélection O(n²)","Quicksort O(n log n)","Tous équivalents"],"ans":2,"exp":"Quicksort/Mergesort en O(n log n) sont bien plus rapides pour grands n. Pour n=10⁶ : O(n²)=10¹² vs O(n log n)=2×10⁷."},{"q":"Recherche dichotomique exige :","opts":["Tableau non trié","Tableau trié","Tableau vide","Récursion"],"ans":1,"exp":"Dichotomie requiert un tableau trié. Coupe en 2 à chaque étape. Complexité O(log n)."},{"q":"Pour n=1024, log₂(n) =","opts":["10","100","1024","2"],"ans":0,"exp":"2¹⁰ = 1024 donc log₂(1024) = 10. Très efficace : dichotomie sur 1024 éléments = 10 comparaisons max."},{"q":"Complexité de l'accès t[i] dans un tableau :","opts":["O(log n)","O(n)","O(1)","O(n²)"],"ans":2,"exp":"Accès direct via indice = O(1) = constant. C'est la force des tableaux vs listes chaînées."},{"q":"Tri sur [3,1,2] avec tri à bulles, 1er échange :","opts":["Aucun","3 et 1","1 et 2","3 et 2"],"ans":1,"exp":"Compare 3 et 1 → 3>1 donc échange → [1,3,2]. Puis compare 3 et 2 → [1,2,3] trié."}]},"lv42":{"experience":["1️⃣ Observe the prepared onion root tip slide: identify cells in interphase (most numerous) and the four mitosis phases.","2️⃣ Draw one cell in METAPHASE: chromosomes aligned on the equator, spindle fibres attached to centromeres.","3️⃣ Count 50 cells and record how many are in each phase → estimate the relative duration of each phase.","4️⃣ Compare with a meiosis diagram: spot crossing-over (chiasmata) in Prophase I.","5️⃣ Build the comparison table: number of divisions, daughter cells, chromosome number, genetic identity."],"quiz":[{"q":"Mitosis produces:","opts":["4 haploid cells","2 identical diploid cells","2 haploid cells","4 different diploid cells"],"ans":1,"exp":"Mitosis = one division, two genetically identical diploid daughter cells."},{"q":"Crossing-over happens during:","opts":["Metaphase II","Prophase I","Anaphase II","Telophase I"],"ans":1,"exp":"Crossing-over (exchange between homologous chromatids) occurs in Prophase I of meiosis."},{"q":"In humans (2n = 46), a gamete contains:","opts":["46 chromosomes","92 chromosomes","23 chromosomes","12 chromosomes"],"ans":2,"exp":"Meiosis halves the number: n = 23 chromosomes in sperm and egg cells."},{"q":"The phase where chromosomes line up at the equator:","opts":["Prophase","Metaphase","Anaphase","Telophase"],"ans":1,"exp":"Metaphase = Middle: chromosomes align on the metaphase plate."}]},"lv45":{"experience":["1️⃣ Observe la pièce en perspective (cale étagée percée). Choisis la vue de face = la plus représentative.","2️⃣ Trace le cadre et le cartouche aux instruments (format A4, échelle 1:1).","3️⃣ Dessine la vue de face : arêtes vues en trait fort, perçage caché en interrompu fin, axes en mixte fin.","4️⃣ Déduis la vue de dessus par correspondance verticale (lignes de rappel).","5️⃣ Déduis la vue de gauche par correspondance horizontale (utilise la ligne à 45°).","6️⃣ Cote la pièce : longueur, largeur, hauteur, position et diamètre du perçage (Ø)."],"quiz":[{"q":"En méthode européenne, la vue de dessus se place :","opts":["au-dessus de la vue de face","en dessous de la vue de face","à gauche","à droite"],"ans":1,"exp":"Méthode E : l'objet est entre l'œil et le plan → la vue de dessus se projette EN DESSOUS."},{"q":"Les arêtes cachées se tracent en :","opts":["trait fort continu","trait interrompu fin","trait mixte fin","trait fin continu"],"ans":1,"exp":"Arêtes cachées = trait interrompu fin (pointillés)."},{"q":"Un diamètre se cote avec le symbole :","opts":["R","Ø","D","⌀⌀"],"ans":1,"exp":"Ø devant la valeur (ex. Ø12) ; R est réservé aux rayons."},{"q":"Le trait mixte fin sert à représenter :","opts":["les contours vus","les axes de symétrie","les hachures","le cartouche"],"ans":1,"exp":"Axes et plans de symétrie = trait mixte fin (tiret-point)."}]}}
JSON;
return json_decode($VRT_LABOS_JSON, true);
